red ='\u001b[31;1m'
gre = '\u001b[32;1m'
yel = '\u001b[33;1m'
blu = '\u001b[34;1m'
mag = '\u001b[35;1m'
cya = '\u001b[36;1m'
whi = '\u001b[37m'
res = '\u001b[0m'
res2 = '\u001b[0m'


class PointerInfo:
	ourPointers = {}
	nextPointerNum = 1

	def __init__(self, pointerNum=0, syscallSeqNum=0, syscallName="", paramNum=0, paramType="", paramName="", value=0, memLoc=0, parentPointerNum=0, fieldPath=""):
		self.pointerNum = pointerNum
		self.syscallSeqNum = syscallSeqNum
		self.syscallName = syscallName
		self.paramNum = paramNum
		self.paramType = paramType
		self.paramName = paramName
		self.value = value
		self.memLoc = memLoc
		self.parentPointerNum = parentPointerNum
		self.fieldPath = fieldPath

	@classmethod
	def clearAllPointers(cls):
		cls.ourPointers = {}
		cls.nextPointerNum = 1

	@staticmethod
	def looksLikePointerType(paramType):
		paramType = str(paramType).strip()
		return paramType.startswith("P") or "*" in paramType

	@staticmethod
	def cleanParamName(paramName):
		return str(paramName).strip().lstrip("*")

	@staticmethod
	def buildMemLoc(pointerNum):
		offset = 0x20 + ((pointerNum - 1) * 4)
		return f"[ebp-0x{offset:X}]"

	@classmethod
	def addPointer(cls, syscallSeqNum, syscallName, paramNum, paramType, paramName, value=0, memLoc=0, parentPointerNum=0, fieldPath=""):
		pointerNum = cls.nextPointerNum
		cls.nextPointerNum += 1
		entry = cls(pointerNum, syscallSeqNum, syscallName, paramNum, paramType, paramName, value, memLoc, parentPointerNum, fieldPath)
		cls.ourPointers[pointerNum] = entry
		return entry

	@staticmethod
	def _getTypeDef(typeRegistry, typeName):
		if typeName in typeRegistry.get("types", {}):
			return typeRegistry["types"][typeName]
		if typeName in typeRegistry.get("primitives", {}):
			return typeRegistry["primitives"][typeName]
		if typeName in typeRegistry.get("enums", {}):
			return typeRegistry["enums"][typeName]
		return None

	@classmethod
	def _resolveTypedef(cls, typeRegistry, typeName):
		seen = set()
		current = typeName

		while True:
			if current in seen:
				return current, cls._getTypeDef(typeRegistry, current)

			seen.add(current)
			typeDef = cls._getTypeDef(typeRegistry, current)
			if not typeDef:
				return current, None

			if typeDef.get("kind") != "typedef":
				return current, typeDef

			current = typeDef.get("target")

	@classmethod
	def _isVoidType(cls, typeRegistry, typeName):
		resolvedName, typeDef = cls._resolveTypedef(typeRegistry, typeName)
		if not typeDef:
			return False
		return typeDef.get("kind") == "void"

	@classmethod
	def _getPointeeType(cls, typeRegistry, paramType):
		resolvedName, typeDef = cls._resolveTypedef(typeRegistry, paramType)

		if typeDef and typeDef.get("kind") == "pointer":
			return typeDef.get("to")

		if str(paramType).endswith("*"):
			baseType = str(paramType).rstrip("*").strip()
			if cls._getTypeDef(typeRegistry, baseType):
				return baseType

		if str(paramType).startswith("P"):
			baseType = str(paramType)[1:]
			if cls._getTypeDef(typeRegistry, baseType):
				return baseType

		return None

	@staticmethod
	def _inlinePointerTypeName(inlineType):
		toType = str(inlineType.get("to", "VOID"))
		if toType == "VOID":
			return "PVOID"
		if toType.startswith("P"):
			return f"{toType}*"
		return f"P{toType}"

	@classmethod
	def _walkNamedType(cls, typeRegistry, typeName, syscallSeqNum, syscallName, rootParamNum, parentPointerNum, pathPrefix, visited):
		resolvedName, typeDef = cls._resolveTypedef(typeRegistry, typeName)
		if not typeDef:
			return

		kind = typeDef.get("kind")

		if kind == "struct":
			if resolvedName in visited:
				return
			nextVisited = set(visited)
			nextVisited.add(resolvedName)
			cls._walkFields(typeRegistry, typeDef.get("fields", []), syscallSeqNum, syscallName, rootParamNum, parentPointerNum, pathPrefix, nextVisited)
			return

		if kind == "union":
			if resolvedName in visited:
				return
			nextVisited = set(visited)
			nextVisited.add(resolvedName)
			cls._walkMembers(typeRegistry, typeDef.get("members", []), syscallSeqNum, syscallName, rootParamNum, parentPointerNum, pathPrefix, nextVisited)
			return

		# arrays intentionally not expanded here; that can explode counts and needs a later count-aware policy

	@classmethod
	def _walkFields(cls, typeRegistry, fields, syscallSeqNum, syscallName, rootParamNum, parentPointerNum, pathPrefix, visited):
		for field in fields:
			fieldName = field.get("name", "<anon>")
			childPath = f"{pathPrefix}.{fieldName}" if pathPrefix else fieldName

			if "type" in field:
				fieldType = field["type"]

				if cls.looksLikePointerType(fieldType):
					memLoc = cls.buildMemLoc(cls.nextPointerNum)
					child = cls.addPointer(syscallSeqNum, syscallName, rootParamNum, fieldType, childPath, 0, memLoc, parentPointerNum, childPath)

					pointeeType = cls._getPointeeType(typeRegistry, fieldType)
					if pointeeType and not cls._isVoidType(typeRegistry, pointeeType):
						cls._walkNamedType(typeRegistry, pointeeType, syscallSeqNum, syscallName, rootParamNum, child.pointerNum, "", visited)
				else:
					cls._walkNamedType(typeRegistry, fieldType, syscallSeqNum, syscallName, rootParamNum, parentPointerNum, childPath, visited)

			elif "type_inline" in field:
				cls._walkInlineType(typeRegistry, field["type_inline"], syscallSeqNum, syscallName, rootParamNum, parentPointerNum, childPath, visited)

	@classmethod
	def _walkMembers(cls, typeRegistry, members, syscallSeqNum, syscallName, rootParamNum, parentPointerNum, pathPrefix, visited):
		for member in members:
			memberName = member.get("name", "<anon>")
			childPath = f"{pathPrefix}.{memberName}" if pathPrefix else memberName

			if "type" in member:
				memberType = member["type"]

				if cls.looksLikePointerType(memberType):
					memLoc = cls.buildMemLoc(cls.nextPointerNum)
					child = cls.addPointer(syscallSeqNum, syscallName, rootParamNum, memberType, childPath, 0, memLoc, parentPointerNum, childPath)

					pointeeType = cls._getPointeeType(typeRegistry, memberType)
					if pointeeType and not cls._isVoidType(typeRegistry, pointeeType):
						cls._walkNamedType(typeRegistry, pointeeType, syscallSeqNum, syscallName, rootParamNum, child.pointerNum, "", visited)
				else:
					cls._walkNamedType(typeRegistry, memberType, syscallSeqNum, syscallName, rootParamNum, parentPointerNum, childPath, visited)

			elif "type_inline" in member:
				cls._walkInlineType(typeRegistry, member["type_inline"], syscallSeqNum, syscallName, rootParamNum, parentPointerNum, childPath, visited)

	@classmethod
	def _walkInlineType(cls, typeRegistry, inlineType, syscallSeqNum, syscallName, rootParamNum, parentPointerNum, pathPrefix, visited):
		kind = inlineType.get("kind")

		if kind == "pointer":
			pointerType = cls._inlinePointerTypeName(inlineType)
			memLoc = cls.buildMemLoc(cls.nextPointerNum)
			child = cls.addPointer(syscallSeqNum, syscallName, rootParamNum, pointerType, pathPrefix, 0, memLoc, parentPointerNum, pathPrefix)

			pointeeType = inlineType.get("to")
			if pointeeType and not cls._isVoidType(typeRegistry, pointeeType):
				cls._walkNamedType(typeRegistry, pointeeType, syscallSeqNum, syscallName, rootParamNum, child.pointerNum, "", visited)
			return

		if kind == "struct":
			cls._walkFields(typeRegistry, inlineType.get("fields", []), syscallSeqNum, syscallName, rootParamNum, parentPointerNum, pathPrefix, visited)
			return

		if kind == "union":
			cls._walkMembers(typeRegistry, inlineType.get("members", []), syscallSeqNum, syscallName, rootParamNum, parentPointerNum, pathPrefix, visited)
			return

		# arrays intentionally skipped for now

	@classmethod
	def buildFromSyscalls(cls, syscallChoices, syscall_signature, typeRegistry):
		cls.clearAllPointers()

		for syscallSeqNum, mySyscall in enumerate(syscallChoices):
			if mySyscall not in syscall_signature:
				continue

			prototype = syscall_signature[mySyscall]
			typeList = prototype[1]
			nameList = prototype[2]

			for paramNum, (paramType, paramName) in enumerate(zip(typeList, nameList)):
				cleanName = cls.cleanParamName(paramName)

				if cls.looksLikePointerType(paramType):
					memLoc = cls.buildMemLoc(cls.nextPointerNum)
					root = cls.addPointer(syscallSeqNum, mySyscall, paramNum, paramType, cleanName, 0, memLoc, 0, cleanName)

					pointeeType = cls._getPointeeType(typeRegistry, paramType)
					if pointeeType and not cls._isVoidType(typeRegistry, pointeeType):
						cls._walkNamedType(typeRegistry, pointeeType, syscallSeqNum, mySyscall, paramNum, root.pointerNum, "", set())

		return cls.ourPointers

	@classmethod
	def buildChildLookup(cls):
		childLookup = {}

		for pointerNum in sorted(cls.ourPointers):
			p = cls.ourPointers[pointerNum]
			if not p.parentPointerNum:
				continue

			if p.parentPointerNum not in childLookup:
				childLookup[p.parentPointerNum] = {}

			childLookup[p.parentPointerNum][p.fieldPath] = p.pointerNum

		return childLookup

	@classmethod
	def printPointers(cls):
		for pointerNum in sorted(cls.ourPointers):
			p = cls.ourPointers[pointerNum]
			print(f"{p.pointerNum}: syscall={p.syscallName}, syscallSeqNum={p.syscallSeqNum}, paramNum={p.paramNum}, type={p.paramType}, name={p.paramName}, value={p.value}, memLoc={p.memLoc}, parent={p.parentPointerNum}, fieldPath={p.fieldPath}")

	@classmethod
	def getRootPointerForParam(cls, syscallSeqNum, syscallName, paramNum):
		for pointerNum in sorted(cls.ourPointers):
			p = cls.ourPointers[pointerNum]
			if getattr(p, "parentPointerNum", 0):
				continue
			if p.syscallSeqNum == syscallSeqNum and p.syscallName == syscallName and p.paramNum == paramNum:
				return p
		return None


def _inlinePointerTypeSizeName(inlineType):
	toType = str(inlineType.get("to", "VOID"))
	pointerSize = inlineType.get("pointer_size", None)

	if toType == "VOID":
		if pointerSize == 8:
			return "PVOID64"
		return "PVOID"

	if toType.startswith("P"):
		return f"{toType}*"

	return f"P{toType}"

def buildChildLookupFromPointers(ourPointers):
	childLookup = {}

	for pointerNum in sorted(ourPointers):
		p = ourPointers[pointerNum]
		parentPointerNum = getattr(p, "parentPointerNum", 0)
		fieldPath = getattr(p, "fieldPath", "")

		if not parentPointerNum:
			continue
		if not fieldPath:
			continue

		if parentPointerNum not in childLookup:
			childLookup[parentPointerNum] = {}

		childLookup[parentPointerNum][fieldPath] = pointerNum

	return childLookup

def _is_void_type(typeRegistry, typeName):
	resolvedName, typeDef = _resolve_typedef(typeRegistry, typeName)
	if not typeDef:
		return False
	return typeDef.get("kind") == "void"

def _get_type_def(typeRegistry, typeName):
	if typeName in typeRegistry.get("types", {}):
		return typeRegistry["types"][typeName]
	if typeName in typeRegistry.get("primitives", {}):
		return typeRegistry["primitives"][typeName]
	if typeName in typeRegistry.get("enums", {}):
		return typeRegistry["enums"][typeName]
	return None


def _resolve_typedef(typeRegistry, typeName):
	seen = set()
	current = typeName

	while True:
		if current in seen:
			return current, _get_type_def(typeRegistry, current)

		seen.add(current)
		typeDef = _get_type_def(typeRegistry, current)
		if not typeDef:
			return current, None

		if typeDef.get("kind") != "typedef":
			return current, typeDef

		current = typeDef.get("target")


def _type_size(typeRegistry, typeName, arch="x86"):
	resolvedName, typeDef = _resolve_typedef(typeRegistry, typeName)
	if not typeDef:
		return 4

	kind = typeDef.get("kind")

	if kind == "pointer":
		sizeField = typeDef.get("size", {"x86": 4, "x64": 8})
		if isinstance(sizeField, dict):
			return sizeField.get(arch, 4)
		return sizeField

	if "size" in typeDef:
		sizeField = typeDef["size"]
		if isinstance(sizeField, dict):
			return sizeField.get(arch, 4)
		return sizeField

	if kind == "enum":
		return 4

	if kind == "typedef":
		return _type_size(typeRegistry, typeDef.get("target"), arch=arch)

	if kind == "struct":
		total = 0
		for field in typeDef.get("fields", []):
			total += _field_size(typeRegistry, field, arch=arch)
		return total

	if kind == "union":
		maxSize = 0
		for member in typeDef.get("members", []):
			maxSize = max(maxSize, _field_size(typeRegistry, member, arch=arch))
		return maxSize

	if kind == "array":
		count = typeDef.get("count", 0)
		elemType = typeDef.get("elementType")
		elemSize = _type_size(typeRegistry, elemType, arch=arch)
		return count * elemSize

	return 4


def _field_size(typeRegistry, fieldDef, arch="x86"):
	if "type" in fieldDef:
		return _type_size(typeRegistry, fieldDef["type"], arch=arch)
	if "type_inline" in fieldDef:
		inlineType = fieldDef["type_inline"]
		return _inline_type_size(typeRegistry, inlineType, arch=arch)
	return 4


def _inline_type_size(typeRegistry, inlineType, arch="x86"):
	kind = inlineType.get("kind")

	if "size" in inlineType:
		sizeField = inlineType["size"]
		if isinstance(sizeField, dict):
			return sizeField.get(arch, 4)
		return sizeField

	if kind == "pointer":
		sizeField = inlineType.get("size", {"x86": 4, "x64": 8})
		if isinstance(sizeField, dict):
			return sizeField.get(arch, 4)
		return sizeField

	if kind == "struct":
		total = 0
		for field in inlineType.get("fields", []):
			total += _field_size(typeRegistry, field, arch=arch)
		return total

	if kind == "union":
		maxSize = 0
		for member in inlineType.get("members", []):
			maxSize = max(maxSize, _field_size(typeRegistry, member, arch=arch))
		return maxSize

	return 4


def _get_pointee_type(typeRegistry, paramType):
	resolvedName, typeDef = _resolve_typedef(typeRegistry, paramType)

	if typeDef and typeDef.get("kind") == "pointer":
		return typeDef.get("to")

	if paramType.endswith("*"):
		baseType = paramType.rstrip("*").strip()
		if _get_type_def(typeRegistry, baseType):
			return baseType

	if paramType.startswith("P"):
		baseType = paramType[1:]
		if _get_type_def(typeRegistry, baseType):
			return baseType

	return None


def _build_pointers_by_syscall(ourPointers):
	out = {}
	for pointerNum in sorted(ourPointers.keys()):
		p = ourPointers[pointerNum]
		key = (p.syscallSeqNum, p.syscallName)
		if key not in out:
			out[key] = []
		out[key].append(p)

	for key in out:
		out[key].sort(key=lambda x: (x.paramNum, x.pointerNum))

	return out


def _parse_pointer_ref(rawValue):
	if isinstance(rawValue, str) and rawValue.lower().startswith("ptr:"):
		tail = rawValue.split(":", 1)[1].strip()
		if tail.isdigit():
			return int(tail)
	return None


def _mem_operand(memLoc):
	memLoc = str(memLoc).strip()
	if memLoc.startswith("["):
		return f"dword {memLoc}"
	return f"dword [{memLoc}]"


def _fmtAsmComment(asmText, comment="", color=None, width=36):
	if not comment:
		return asmText
	if color is None:
		color = yel
	return f"{asmText:<{width}}\t; {color}{comment}{res}"


def _typeComment(typeName, fieldName=""):
	if fieldName:
		return f"{typeName} {fieldName}"
	return str(typeName)


def _emit_zero_push(size, state, comment=""):
    out = []

    if size == 4:
        if not state.get("zero32Ready", False):
            out.append("xor ebx, ebx")
            state["zero32Ready"] = True
        out.append(_fmtAsmComment("push ebx", comment))
        return out

    if size == 2:
        if not state.get("zero16Ready", False):
            out.append("xor edx, edx")
            state["zero16Ready"] = True
        out.append(_fmtAsmComment("push dx", comment))
        return out

    if size == 1:
        if not state.get("zero32Ready", False):
            out.append("xor ebx, ebx")
            state["zero32Ready"] = True
        out.append("sub esp, 1")
        out.append(_fmtAsmComment("mov byte ptr [esp], bl", comment))
        return out

    if size == 8:
        if not state.get("zero32Ready", False):
            out.append("xor ebx, ebx")
            state["zero32Ready"] = True
        out.append(_fmtAsmComment("push ebx", comment))
        out.append(_fmtAsmComment("push ebx", comment))
        return out

    raise NotImplementedError(f"push-only zero emission does not support size {size}")


def _emit_imm_push(value, size, state, comment=""):
    if value == 0 or value is None:
        return _emit_zero_push(size, state, comment)

    if size == 4:
        return [_fmtAsmComment(f"push 0x{value & 0xFFFFFFFF:X}", comment)]

    if size == 2:
        return [f"mov dx, 0x{value & 0xFFFF:X}", _fmtAsmComment("push dx", comment)]

    if size == 1:
        return ["sub esp, 1", _fmtAsmComment(f"mov byte ptr [esp], 0x{value & 0xFF:X}", comment)]

    if size == 8:
        high = (value >> 32) & 0xFFFFFFFF
        low = value & 0xFFFFFFFF
        return [_fmtAsmComment(f"push 0x{high:X}", comment), _fmtAsmComment(f"push 0x{low:X}", comment)]

    raise NotImplementedError(f"push-only immediate emission does not support size {size}")

def _emit_pointer_build(pointerEntry, ourPointers, typeRegistry, builtSet, arch="x86", childLookup=None):
	if pointerEntry.pointerNum in builtSet:
		return []

	state = {"zero32Ready": False, "zero16Ready": False}
	out = []
	directChildren = []
	pointeeType = _get_pointee_type(typeRegistry, pointerEntry.paramType)
	nullLookupTypeName = pointeeType

	if childLookup and pointerEntry.pointerNum in childLookup:
		for fieldPath, childPointerNum in childLookup[pointerEntry.pointerNum].items():
			childEntry = ourPointers[childPointerNum]
			if _nullLookupSaysNull(nullLookupTypeName, fieldPath, childEntry.value):
				continue
			directChildren.append((fieldPath, childPointerNum))

	directChildren.sort(key=lambda x: ourPointers[x[1]].pointerNum)

	for fieldPath, childPointerNum in directChildren:
		childEntry = ourPointers[childPointerNum]
		out.extend(_emit_pointer_build(childEntry, ourPointers, typeRegistry, builtSet, arch=arch, childLookup=childLookup))
		out.append("")

	rawValue = pointerEntry.value
	out.append(f"; {cya}{pointerEntry.paramType} {pointerEntry.paramName}{res}")

	if pointeeType is None:
		out.extend(_emit_scalar_like(typeRegistry, pointerEntry.paramType, rawValue, ourPointers, builtSet, state, arch=arch, comment=_typeComment(pointerEntry.paramType, pointerEntry.paramName)))
		out.append(_fmtAsmComment(f"mov {_mem_operand(pointerEntry.memLoc)}, esp", pointerEntry.paramName, red))
		builtSet.add(pointerEntry.pointerNum)
		return out

	if _is_void_type(typeRegistry, pointeeType):
		out.extend(_emit_scalar_like(typeRegistry, pointerEntry.paramType, rawValue, ourPointers, builtSet, state, arch=arch, comment=_typeComment(pointerEntry.paramType, pointerEntry.paramName)))
		out.append(_fmtAsmComment(f"mov {_mem_operand(pointerEntry.memLoc)}, esp", pointerEntry.paramName, red))
		builtSet.add(pointerEntry.pointerNum)
		return out

	out.extend(_emit_value(typeRegistry, pointeeType, rawValue, ourPointers, builtSet, state, arch=arch, ownerPointerNum=pointerEntry.pointerNum, childLookup=childLookup, fieldPath="", commentLabel=pointerEntry.paramName, nullLookupTypeName=pointeeType))
	out.append(_fmtAsmComment(f"mov {_mem_operand(pointerEntry.memLoc)}, esp", pointerEntry.paramName, red))
	builtSet.add(pointerEntry.pointerNum)
	return out

def _emit_pointer_slot_ref(pointerNum, ourPointers, comment=""):
	if pointerNum not in ourPointers:
		raise KeyError(f"pointer {pointerNum} not found in ourPointers")
	return [_fmtAsmComment(f"push {_mem_operand(ourPointers[pointerNum].memLoc)}", comment)]


def _emit_scalar_like(typeRegistry, typeName, rawValue, ourPointers, builtSet, state, arch="x86", comment=""):
	refNum = _parse_pointer_ref(rawValue)
	if refNum is not None:
		return _emit_pointer_slot_ref(refNum, ourPointers, comment)
	size = _type_size(typeRegistry, typeName, arch=arch)
	return _emit_imm_push(rawValue, size, state, comment)


def _find_child_pointer_num(childLookup, ownerPointerNum, fieldPath):
	if not ownerPointerNum or ownerPointerNum not in childLookup:
		return None
	return childLookup[ownerPointerNum].get(fieldPath)


def _find_union_member_from_children(childLookup, ownerPointerNum, unionPath):
	if not ownerPointerNum or ownerPointerNum not in childLookup:
		return None

	prefix = unionPath + "."
	directMembers = []

	for fieldPath in childLookup[ownerPointerNum]:
		if fieldPath.startswith(prefix):
			tail = fieldPath[len(prefix):]
			memberName = tail.split(".", 1)[0]
			if memberName not in directMembers:
				directMembers.append(memberName)

	if len(directMembers) == 1:
		return directMembers[0]

	return None


def _getNullLookupTable():
	if isinstance(NT_NULL_LOOKUP, dict) and "nullLookup" in NT_NULL_LOOKUP:
		return NT_NULL_LOOKUP["nullLookup"]
	return NT_NULL_LOOKUP


def _isDefaultNullValue(rawValue):
	if rawValue is None:
		return True
	if rawValue == 0:
		return True
	if isinstance(rawValue, dict) and len(rawValue) == 0:
		return True
	return False


def _nullLookupSaysNull(rootTypeName, fieldPath, rawValue=0):
	if not rootTypeName or not fieldPath:
		return False
	if not _isDefaultNullValue(rawValue):
		return False

	cur = _getNullLookupTable().get(rootTypeName)
	if not isinstance(cur, dict):
		return False

	for piece in str(fieldPath).split("."):
		if not isinstance(cur, dict) or piece not in cur:
			return False
		cur = cur[piece]

	return cur is True


def _emitNullForType(typeRegistry, typeName, state, arch="x86", comment=""):
	size = _type_size(typeRegistry, typeName, arch=arch)
	return _emit_imm_push(0, size, state, comment)


def _emitNullForInlineType(typeRegistry, inlineType, state, arch="x86", comment=""):
	size = _inline_type_size(typeRegistry, inlineType, arch=arch)
	return _emit_imm_push(0, size, state, comment)

def generatePointerBuildAssembly(ourSyscalls, ourPointers, typeRegistry, arch="x86"):
	pointersBySyscall = _build_pointers_by_syscall(ourPointers)
	childLookup = buildChildLookupFromPointers(ourPointers)
	builtSet = set()
	out = []

	for syscallSeqNum, mySyscall in enumerate(ourSyscalls):
		key = (syscallSeqNum, mySyscall)
		pointerList = pointersBySyscall.get(key, [])
		if not pointerList:
			continue

		out.append(f"; {gre}pointers for syscall {syscallSeqNum}: {mySyscall}{res}")

		for pointerEntry in pointerList:
			if getattr(pointerEntry, "parentPointerNum", 0) or getattr(pointerEntry, "skipBuild", False):
				continue
			out.extend(_emit_pointer_build(pointerEntry, ourPointers, typeRegistry, builtSet, arch=arch, childLookup=childLookup))
			out.append("")

	return "\n".join(out).rstrip() + "\n\n"


def _emit_inline_value(typeRegistry, inlineType, rawValue, ourPointers, builtSet, state, arch="x86", ownerPointerNum=0, childLookup=None, fieldPath="", commentLabel="", nullLookupTypeName=""):
	kind = inlineType.get("kind")

	if kind == "pointer":
		inlinePointerType = _inlinePointerTypeSizeName(inlineType)
		comment = _typeComment(inlinePointerType, commentLabel)

		if _nullLookupSaysNull(nullLookupTypeName, fieldPath, rawValue):
			return _emitNullForInlineType(typeRegistry, inlineType, state, arch=arch, comment=comment)

		childPointerNum = _find_child_pointer_num(childLookup, ownerPointerNum, fieldPath)
		if childPointerNum is not None:
			return _emit_pointer_slot_ref(childPointerNum, ourPointers, comment)

		refNum = _parse_pointer_ref(rawValue)
		if refNum is not None:
			return _emit_pointer_slot_ref(refNum, ourPointers, comment)

		size = _inline_type_size(typeRegistry, inlineType, arch=arch)
		return _emit_imm_push(rawValue, size, state, comment)

	if kind == "struct":
		if _nullLookupSaysNull(nullLookupTypeName, fieldPath, rawValue):
			return _emitNullForInlineType(typeRegistry, inlineType, state, arch=arch, comment=_typeComment("STRUCT", commentLabel))

		valueMap = rawValue if isinstance(rawValue, dict) else {}
		return _emit_inline_struct(typeRegistry, inlineType, valueMap, ourPointers, builtSet, state, arch=arch, ownerPointerNum=ownerPointerNum, childLookup=childLookup, pathPrefix=fieldPath, nullLookupTypeName=nullLookupTypeName)

	if kind == "union":
		if _nullLookupSaysNull(nullLookupTypeName, fieldPath, rawValue):
			return _emitNullForInlineType(typeRegistry, inlineType, state, arch=arch, comment=_typeComment("UNION", commentLabel))

		return _emit_inline_union(typeRegistry, inlineType, rawValue, ourPointers, builtSet, state, arch=arch, ownerPointerNum=ownerPointerNum, childLookup=childLookup, pathPrefix=fieldPath, commentLabel=commentLabel, nullLookupTypeName=nullLookupTypeName)

	size = _inline_type_size(typeRegistry, inlineType, arch=arch)
	return _emit_imm_push(rawValue, size, state, _typeComment(str(kind).upper(), commentLabel))


def _emit_value(typeRegistry, typeName, rawValue, ourPointers, builtSet, state, arch="x86", ownerPointerNum=0, childLookup=None, fieldPath="", commentLabel="", nullLookupTypeName=""):
	resolvedName, typeDef = _resolve_typedef(typeRegistry, typeName)
	if not typeDef:
		return _emit_imm_push(rawValue, 4, state, _typeComment(typeName, commentLabel))

	if not nullLookupTypeName:
		nullLookupTypeName = resolvedName

	if _nullLookupSaysNull(nullLookupTypeName, fieldPath, rawValue):
		return _emitNullForType(typeRegistry, typeName, state, arch=arch, comment=_typeComment(typeName, commentLabel))

	kind = typeDef.get("kind")

	if kind == "struct":
		valueMap = rawValue if isinstance(rawValue, dict) else {}
		return _emit_struct(typeRegistry, resolvedName, valueMap, ourPointers, builtSet, state, arch=arch, ownerPointerNum=ownerPointerNum, childLookup=childLookup, pathPrefix=fieldPath, nullLookupTypeName=nullLookupTypeName)

	if kind == "union":
		return _emit_union(typeRegistry, resolvedName, rawValue, ourPointers, builtSet, state, arch=arch, ownerPointerNum=ownerPointerNum, childLookup=childLookup, pathPrefix=fieldPath, commentLabel=commentLabel, nullLookupTypeName=nullLookupTypeName)

	if kind == "pointer":
		childPointerNum = _find_child_pointer_num(childLookup, ownerPointerNum, fieldPath)
		if childPointerNum is not None:
			return _emit_pointer_slot_ref(childPointerNum, ourPointers, _typeComment(resolvedName, commentLabel))

	return _emit_scalar_like(typeRegistry, resolvedName, rawValue, ourPointers, builtSet, state, arch=arch, comment=_typeComment(resolvedName, commentLabel))


def _emit_struct(typeRegistry, structTypeName, valueMap, ourPointers, builtSet, state, arch="x86", ownerPointerNum=0, childLookup=None, pathPrefix="", nullLookupTypeName=""):
	resolvedName, structDef = _resolve_typedef(typeRegistry, structTypeName)
	if not structDef or structDef.get("kind") != "struct":
		raise TypeError(f"{structTypeName} is not a struct")

	if not nullLookupTypeName:
		nullLookupTypeName = resolvedName

	out = []
	fields = structDef.get("fields", [])

	for field in reversed(fields):
		fieldName = field["name"]
		fullFieldPath = fieldName if not pathPrefix else f"{pathPrefix}.{fieldName}"
		rawValue = valueMap.get(fieldName, 0)

		if "type" in field:
			out.extend(_emit_value(typeRegistry, field["type"], rawValue, ourPointers, builtSet, state, arch=arch, ownerPointerNum=ownerPointerNum, childLookup=childLookup, fieldPath=fullFieldPath, commentLabel=fieldName, nullLookupTypeName=nullLookupTypeName))
		elif "type_inline" in field:
			out.extend(_emit_inline_value(typeRegistry, field["type_inline"], rawValue, ourPointers, builtSet, state, arch=arch, ownerPointerNum=ownerPointerNum, childLookup=childLookup, fieldPath=fullFieldPath, commentLabel=fieldName, nullLookupTypeName=nullLookupTypeName))
		else:
			out.extend(_emit_zero_push(4, state, fieldName))

	return out


def _emit_inline_struct(typeRegistry, structDef, valueMap, ourPointers, builtSet, state, arch="x86", ownerPointerNum=0, childLookup=None, pathPrefix="", nullLookupTypeName=""):
	out = []
	fields = structDef.get("fields", [])

	for field in reversed(fields):
		fieldName = field["name"]
		fullFieldPath = fieldName if not pathPrefix else f"{pathPrefix}.{fieldName}"
		rawValue = valueMap.get(fieldName, 0)

